<template>
  <section class="mci-page-enter">
    <MciPageIntro eyebrow="OBSERVABILITY" title="链路、日志生命周期与告警闭环" description="W3C Trace 串联 HTTP、后台任务与消息队列；日志归档先计划、再持久化、校验、删除；告警按路由和值班链留下送达证据。">
      <button type="button" class="mci-button" @click="logPolicyOpen = true">新建日志策略</button>
      <button type="button" class="mci-button" @click="routeOpen = true">新建告警路由</button>
