      <article class="mci-card mci-section span-8">
        <div class="mci-section__head"><div><h2>活动告警</h2><p>显式状态机和期望状态避免多人处置互相覆盖。</p></div><span class="mci-badge" :data-tone="highCount ? 'danger' : data.Alerts.length ? 'warning' : 'success'">{{ highCount ? '需要立即处理' : data.Alerts.length ? '需要跟进' : '运行平稳' }}</span></div>
        <MciStatePanel v-if="!data.Alerts.length" state="empty" title="没有活动告警" />
        <MciDataTable v-else :rows="data.Alerts" :columns="alertColumns"><template #actions="{ row }"><div class="table-actions"><button v-if="row.Status === 'New'" type="button" @click="transitionAlert(row, 'Acknowledge')">确认</button><button v-if="['New','Acknowledged'].includes(String(row.Status))" type="button" @click="prepareResolve(row)">解决</button><button v-if="row.Status === 'Resolved'" type="button" @click="transitionAlert(row, 'Close')">关闭</button></div></template></MciDataTable>
      </article>

      <article class="mci-card mci-section span-12 trace-panel">
        <div class="mci-section__head"><div><h2>W3C Trace 时间线</h2><p>按租户查询最近三个月或指定月份，最多返回 500 个脱敏 Span。</p></div><span v-if="traceResult" class="mci-badge" data-tone="primary">{{ traceResult.SpanCount }} spans</span></div>
        <div class="trace-search"><label class="mci-field"><span>32位 TraceId</span><input v-model.trim="traceForm.TraceId" maxlength="32" placeholder="0123456789abcdef0123456789abcdef" /></label><label class="mci-field"><span>月份（可选）</span><input v-model.trim="traceForm.SearchMonth" placeholder="2026-08" /></label><button type="button" class="mci-button mci-button--primary" :disabled="traceBusy" @click="queryTrace">{{ traceBusy ? '查询中…' : '查询链路' }}</button></div>
        <MciStatePanel v-if="!traceResult" state="empty" title="输入 TraceId 查看端到端时间线" />
        <MciStatePanel v-else-if="!traceResult.Spans.length" state="empty" title="没有找到该链路" />
        <div v-else class="trace-timeline"><article v-for="span in traceResult.Spans" :key="String(span.EventId || span.SpanId)" :data-success="span.Success"><span></span><header><strong>{{ span.ServiceName || span.Source || 'Microi' }}</strong><code>{{ span.SpanId }}</code><i>{{ span.DurationMs ?? 0 }}ms</i></header><p>{{ span.Title || span.Action || span.Type }}</p><small>{{ span.CreateTime }} · parent {{ span.ParentSpanId || 'root' }} · HTTP {{ span.HttpStatusCode || '—' }}</small></article></div>
      </article>

      <article class="mci-card mci-section span-7">
        <div class="mci-section__head"><div><h2>日志生命周期策略</h2><p>保留期、配额、脱敏、法律保留和归档方式统一治理。</p></div><span class="mci-badge">{{ logPolicies.length }} 条</span></div>
        <MciStatePanel v-if="!logPolicies.length" state="empty" title="暂无日志策略" action="新建日志策略" @action="logPolicyOpen = true" />
        <MciDataTable v-else :rows="logPolicies" :columns="logPolicyColumns"><template #actions="{ row }"><button type="button" :disabled="action.status === 'loading'" @click="planLifecycle(row)">预览执行</button></template></MciDataTable>
      </article>
      <article class="mci-card mci-section span-5">
        <div class="mci-section__head"><div><h2>归档与删除证据</h2><p>只有归档持久化和回读成功后才删除源日志。</p></div><span class="mci-badge">{{ lifecycleRuns.length }} 次</span></div>
        <MciStatePanel v-if="!lifecycleRuns.length" state="empty" title="暂无生命周期运行" />
        <ol v-else class="run-list"><li v-for="item in lifecycleRuns.slice(0, 10)" :key="String(item.Id)"><span :data-state="item.Status"></span><div><strong>{{ item.Status }} · {{ item.ArchivedCount || 0 }}/{{ item.ScannedCount || 0 }}</strong><small>{{ policyName(item.PolicyId) }} · 删除 {{ item.DeletedCount || 0 }}</small><code>{{ item.ArchiveProofHash || item.RunKey }}</code></div></li></ol>
      </article>

      <article class="mci-card mci-section span-7">
        <div class="mci-section__head"><div><h2>阈值策略</h2><p>可信信号、连续窗口、抑制和恢复共用同一状态机。</p></div><span class="mci-badge">{{ data.Policies.length }} 条启用</span></div>
        <MciStatePanel v-if="!data.Policies.length" state="empty" title="暂无启用策略" action="创建阈值策略" @action="policyOpen = true" />
        <MciDataTable v-else :rows="data.Policies" :columns="policyColumns"><template #actions="{ row }"><button type="button" :disabled="action.status === 'loading'" @click="openPolicyTest(row)">立即评估</button></template></MciDataTable>
      </article>
