        <MciStatePanel v-if="!evaluations.length" state="empty" title="暂无策略评估" />
        <MciDataTable v-else :rows="evaluations.slice(0, 12)" :columns="evaluationColumns" />
      </article>
      <article class="mci-card mci-section span-12">
        <div class="mci-section__head"><div><h2>告警路由与送达</h2><p>匹配、渠道、值班和升级链按优先级执行。</p></div><span class="mci-badge" :data-tone="failedDeliveries ? 'warning' : 'success'">{{ routes.length }} 路由 · {{ deliveries.length }} 证据</span></div>
        <MciStatePanel v-if="!routes.length" state="empty" title="暂无告警路由" action="新建告警路由" @action="routeOpen = true" />
        <div v-else class="route-list"><article v-for="item in routes.slice(0, 8)" :key="String(item.Id)"><span>{{ item.Priority }}</span><div><strong>{{ item.Name }}</strong><small>{{ item.Owner || '未指定负责人' }} · 确认 {{ item.AcknowledgeSlaMinutes }} 分钟</small></div></article></div>
        <MciDataTable v-if="deliveries.length" class="delivery-table" :rows="deliveries.slice(0, 10)" :columns="deliveryColumns" />
      </article>
      <div v-if="action.message" class="feedback span-12" :data-state="action.status" role="status">{{ action.message }}</div>
    </div>

    <MciDialog :open="policyOpen" title="新建阈值策略" confirm-text="创建策略" :busy="action.status === 'loading'" @cancel="policyOpen = false" @confirm="createPolicy">
      <div class="form-grid"><label class="mci-field"><span>策略Key</span><input v-model.trim="policyForm.PolicyKey" placeholder="api-error-rate" /></label><label class="mci-field"><span>策略名称</span><input v-model.trim="policyForm.Name" placeholder="API错误率" /></label><label class="mci-field"><span>指标名称</span><select v-model="policyForm.MetricName"><option>TotalCount</option><option>ErrorCount</option><option>ErrorRate</option><option>P95DurationMs</option><option>NoData</option></select></label><label class="mci-field"><span>评估模式</span><select v-model="policyForm.EvaluationMode"><option>Job</option><option>Manual</option><option>Push</option></select></label><label class="mci-field"><span>比较符</span><select v-model="policyForm.Operator"><option>&gt;</option><option>&gt;=</option><option>&lt;</option><option>&lt;=</option><option>=</option><option>&lt;&gt;</option></select></label><label class="mci-field"><span>阈值</span><input v-model.number="policyForm.Threshold" type="number" step="0.0001" /></label><label class="mci-field"><span>窗口秒数</span><input v-model.number="policyForm.WindowSeconds" type="number" min="60" max="86400" /></label><label class="mci-field"><span>级别</span><select v-model="policyForm.Severity"><option>Info</option><option>Warning</option><option>High</option><option>Critical</option></select></label><label class="mci-field"><span>连续触发窗口</span><input v-model.number="policyForm.ConsecutiveWindows" type="number" min="1" max="20" /></label><label class="mci-field"><span>连续恢复窗口</span><input v-model.number="policyForm.RecoveryWindows" type="number" min="1" max="20" /></label><label class="mci-field"><span>抑制秒数</span><input v-model.number="policyForm.SuppressSeconds" type="number" min="0" max="86400" /></label><label class="mci-field full"><span>可信信号 Query JSON</span><textarea v-model="policyForm.QueryJson" spellcheck="false"></textarea><small>Source：SystemLog / ServiceEdge / FormEngineCount；指标可读取日志数量、错误率、P95 或受限业务表计数。</small></label></div>
    </MciDialog>
    <MciDialog :open="testOpen" title="评估告警策略" confirm-text="评估并记录" :busy="action.status === 'loading'" @cancel="testOpen = false" @confirm="evaluatePolicy">
      <div class="form-grid"><label class="mci-field"><span>策略</span><select v-model="testForm.PolicyId"><option v-for="item in data.Policies" :key="String(item.Id)" :value="String(item.Id)">{{ item.Name }}</option></select></label><label class="hold-check"><input v-model="testForm.UseConfiguredSignal" type="checkbox" /><span>读取策略可信信号</span></label><label v-if="!testForm.UseConfiguredSignal" class="mci-field"><span>模拟观测值</span><input v-model.number="testForm.ObservedValue" type="number" step="0.0001" /></label><label class="mci-field full"><span>稳定事件Id</span><input v-model.trim="testForm.EventId" maxlength="120" /></label></div><p>相同 EventId 重试只返回既有窗口台账；定时策略正常运行时由平台自动生成窗口Key。</p>
    </MciDialog>
    <MciDialog :open="resolveOpen" title="解决告警" confirm-text="记录解决结论" :busy="action.status === 'loading'" @cancel="resolveOpen = false" @confirm="resolveAlert">
      <label class="mci-field"><span>解决结论</span><textarea v-model.trim="resolution" placeholder="根因、处置和验证结果"></textarea></label>
    </MciDialog>
    <MciDialog :open="logPolicyOpen" title="新建日志生命周期策略" confirm-text="创建策略" :busy="action.status === 'loading'" @cancel="logPolicyOpen = false" @confirm="createLogPolicy">
      <div class="form-grid"><label class="mci-field"><span>策略Key</span><input v-model.trim="logPolicyForm.PolicyKey" placeholder="system-log-default" /></label><label class="mci-field"><span>策略名称</span><input v-model.trim="logPolicyForm.Name" /></label><label class="mci-field"><span>来源</span><select v-model="logPolicyForm.SourceType"><option>All</option><option>Application</option><option>System</option><option>Container</option><option>Audit</option></select></label><label class="mci-field"><span>归档方式</span><select v-model="logPolicyForm.ArchiveMode"><option>PrivateHdfs</option><option>Extension</option><option>DeleteOnly</option></select></label><label class="mci-field"><span>热存储天数</span><input v-model.number="logPolicyForm.HotDays" type="number" min="1" /></label><label class="mci-field"><span>温存储天数</span><input v-model.number="logPolicyForm.WarmDays" type="number" min="1" /></label><label class="mci-field"><span>冷存储天数</span><input v-model.number="logPolicyForm.ColdDays" type="number" min="1" /></label><label class="mci-field"><span>总配额 MB</span><input v-model.number="logPolicyForm.TotalQuotaMB" type="number" min="0" /></label><label class="mci-field full"><span>匹配 JSON</span><textarea v-model="logPolicyForm.MatchJson" spellcheck="false"></textarea></label><label class="mci-field full"><span>脱敏规则 JSON</span><textarea v-model="logPolicyForm.RedactionJson" spellcheck="false"></textarea></label><label class="hold-check full"><input v-model="logPolicyForm.LegalHold" type="checkbox" /><span>法律保留（阻止归档删除）</span></label></div>
    </MciDialog>
    <MciDialog :open="lifecycleOpen" title="确认日志生命周期执行" confirm-text="提交持久后台任务" :busy="action.status === 'loading'" @cancel="lifecycleOpen = false" @confirm="executeLifecycle">
      <p>执行顺序固定为：读取分片 → 生成确定性 gzip JSONL → 私有存储持久化 → 对象回读 → 写入回执 → 条件删除 → 删除回读。</p><code class="mci-code">Policy: {{ lifecycleTarget?.Name }}\nCutoff: {{ lifecyclePlan?.Plan?.CutoffTime }}\nEstimated: {{ lifecyclePlan?.EstimatedCount || 0 }}\nArchiveMode: {{ lifecyclePlan?.Plan?.ArchiveMode }}\nPlanHash: {{ lifecyclePlan?.PlanHash }}</code><p v-if="!lifecyclePlan?.CanExecute" class="blocked">{{ lifecyclePlan?.BlockReason }}</p>
    </MciDialog>
    <MciDialog :open="routeOpen" title="新建告警路由" confirm-text="创建路由" :busy="action.status === 'loading'" @cancel="routeOpen = false" @confirm="createRoute">
      <div class="form-grid"><label class="mci-field"><span>路由Key</span><input v-model.trim="routeForm.RouteKey" placeholder="critical-oncall" /></label><label class="mci-field"><span>路由名称</span><input v-model.trim="routeForm.Name" /></label><label class="mci-field"><span>优先级</span><input v-model.number="routeForm.Priority" type="number" min="0" /></label><label class="mci-field"><span>负责人</span><input v-model.trim="routeForm.Owner" /></label><label class="mci-field"><span>确认 SLA 分钟</span><input v-model.number="routeForm.AcknowledgeSlaMinutes" type="number" min="1" /></label><label class="mci-field"><span>解决 SLA 分钟</span><input v-model.number="routeForm.ResolveSlaMinutes" type="number" min="1" /></label><label class="mci-field full"><span>匹配 JSON</span><textarea v-model="routeForm.MatchJson" spellcheck="false"></textarea></label><label class="mci-field full"><span>渠道 JSON</span><textarea v-model="routeForm.ChannelsJson" spellcheck="false"></textarea></label><label class="mci-field full"><span>升级链 JSON</span><textarea v-model="routeForm.EscalationJson" spellcheck="false"></textarea></label></div>
    </MciDialog>
  </section>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import MciDataTable from '../components/MciDataTable.vue'
import MciDialog from '../components/MciDialog.vue'
import MciPageIntro from '../components/MciPageIntro.vue'
import MciStatePanel from '../components/MciStatePanel.vue'
import type { ActionState, HostContext } from '../domain/models'
import { addRow, getTable, runBackground, runEngine } from '../platform/client'

const props = defineProps<{ context: HostContext }>()
type Row = Record<string, any>
interface Overview { Services: Row[]; Policies: Row[]; Alerts: Row[]; GeneratedAt: string }
interface TraceResult { TraceId: string; SpanCount: number; Spans: Row[] }
interface LifecyclePlan { Plan: Row; PlanHash: string; CanExecute: boolean; BlockReason: string; EstimatedCount: number }
const data = ref<Overview>({ Services: [], Policies: [], Alerts: [], GeneratedAt: '' }), logPolicies = ref<Row[]>([]), lifecycleRuns = ref<Row[]>([]), routes = ref<Row[]>([]), deliveries = ref<Row[]>([]), evaluations = ref<Row[]>([])
const state = ref<'loading' | 'ready' | 'error'>('loading'), error = ref(''), action = reactive<ActionState>({ status: 'idle' })
const policyOpen = ref(false), testOpen = ref(false), resolveOpen = ref(false), logPolicyOpen = ref(false), lifecycleOpen = ref(false), routeOpen = ref(false)
const resolveTarget = ref<Row | null>(null), resolution = ref(''), lifecycleTarget = ref<Row | null>(null), lifecyclePlan = ref<LifecyclePlan | null>(null)
const traceForm = reactive({ TraceId: '', SearchMonth: '' }), traceResult = ref<TraceResult | null>(null), traceBusy = ref(false)
const policyForm = reactive({ PolicyKey: '', Name: '', MetricName: 'ErrorRate', EvaluationMode: 'Job', Operator: '>=', Threshold: 0.05, WindowSeconds: 300, Severity: 'Warning', ConsecutiveWindows: 2, RecoveryWindows: 2, SuppressSeconds: 600, QueryJson: '{"Source":"SystemLog","Metric":"ErrorRate","LevelMin":3}' })
const testForm = reactive({ PolicyId: '', ObservedValue: 1, UseConfiguredSignal: true, EventId: `manual-${Date.now()}` })
const logPolicyForm = reactive({ PolicyKey: '', Name: '', SourceType: 'All', ArchiveMode: 'PrivateHdfs', HotDays: 7, WarmDays: 30, ColdDays: 90, DailyQuotaMB: 1024, TotalQuotaMB: 10240, OverQuotaAction: 'Alert', MatchJson: '{}', RedactionJson: '[]', LegalHold: false })
const routeForm = reactive({ RouteKey: '', Name: '', Priority: 100, Owner: '', AcknowledgeSlaMinutes: 15, ResolveSlaMinutes: 120, MatchJson: '{"Severities":["Critical","High"]}', ChannelsJson: '[{"Channel":"TenantExtension","Recipient":"oncall"}]', EscalationJson: '[]' })
const highCount = computed(() => data.value.Alerts.filter((item) => ['Critical', 'High'].includes(item.Severity)).length)
const failedDeliveries = computed(() => deliveries.value.filter((item) => item.Status === 'Failed').length)
const alertColumns = [{ key: 'Title', label: '标题' }, { key: 'Severity', label: '级别', tone: true }, { key: 'Status', label: '状态', tone: true }, { key: 'ObservedValue', label: '观测值' }, { key: 'FirstSeenTime', label: '发现时间' }]
const policyColumns = [{ key: 'Name', label: '策略' }, { key: 'MetricName', label: '指标' }, { key: 'Operator', label: '比较符' }, { key: 'Threshold', label: '阈值' }, { key: 'ConsecutiveWindows', label: '连续' }, { key: 'Severity', label: '级别', tone: true }, { key: 'EvaluationMode', label: '模式' }]
const evaluationColumns = [{ key: 'SignalType', label: '信号' }, { key: 'ObservedValue', label: '观测值' }, { key: 'Triggered', label: '触发', tone: true }, { key: 'Status', label: '状态', tone: true }, { key: 'EvaluatedTime', label: '评估时间' }]
const logPolicyColumns = [{ key: 'Name', label: '策略' }, { key: 'SourceType', label: '来源' }, { key: 'HotDays', label: '热' }, { key: 'WarmDays', label: '温' }, { key: 'ColdDays', label: '冷' }, { key: 'ArchiveMode', label: '归档' }, { key: 'LegalHold', label: '法律保留', tone: true }]
const deliveryColumns = [{ key: 'EventKind', label: '事件' }, { key: 'Channel', label: '渠道' }, { key: 'Recipient', label: '接收目标' }, { key: 'Status', label: '状态', tone: true }, { key: 'AttemptCount', label: '尝试' }, { key: 'DeliveredTime', label: '送达时间' }]
function parseJson(value: string, label: string) { try { return JSON.parse(value || '{}') } catch { throw new Error(`${label}必须是有效 JSON。`) } }
function policyName(id: unknown) { return logPolicies.value.find((item) => String(item.Id) === String(id))?.Name || String(id || '未知策略') }
async function load() { state.value = 'loading'; error.value = ''; try { const [overview, lp, lr, ar, ad, ev] = await Promise.all([runEngine<Overview>(props.context, 'mci-observability-overview'), getTable<Row>(props.context, 'mci_log_policy'), getTable<Row>(props.context, 'mci_log_lifecycle_run'), getTable<Row>(props.context, 'mci_alert_route', { _OrderBy: 'Priority', _OrderByType: 'ASC' }), getTable<Row>(props.context, 'mci_alert_delivery', { _OrderBy: 'CreateTime', _OrderByType: 'DESC', _PageSize: 100 }), getTable<Row>(props.context, 'mci_observability_evaluation', { _OrderBy: 'EvaluatedTime', _OrderByType: 'DESC', _PageSize: 100 })]); data.value = overview; logPolicies.value = lp.rows; lifecycleRuns.value = lr.rows; routes.value = ar.rows; deliveries.value = ad.rows; evaluations.value = ev.rows; testForm.PolicyId ||= String(data.value.Policies[0]?.Id || ''); state.value = 'ready' } catch (e) { error.value = e instanceof Error ? e.message : '加载失败'; state.value = 'error' } }
async function act<T>(work: () => Promise<T>, success: string) { action.status = 'loading'; action.message = ''; try { const result = await work(); action.status = 'success'; action.message = success; return result } catch (e) { action.status = 'error'; action.message = e instanceof Error ? e.message : '执行失败'; return null } }
async function createPolicy() { if (!policyForm.PolicyKey || !policyForm.Name || !policyForm.MetricName) { action.status = 'error'; action.message = '策略Key、名称和指标不能为空。'; return } if (policyForm.WindowSeconds < 60 || policyForm.WindowSeconds > 86400 || policyForm.ConsecutiveWindows < 1 || policyForm.RecoveryWindows < 1) { action.status = 'error'; action.message = '窗口和连续次数超出允许范围。'; return } let query: unknown; try { query = parseJson(policyForm.QueryJson, '可信信号 Query') } catch (e) { action.status = 'error'; action.message = (e as Error).message; return } const result = await act(() => addRow(props.context, 'mci_observability_policy', { ...policyForm, QueryJson: JSON.stringify(query), ConsecutiveTriggerCount: 0, ConsecutiveRecoveryCount: 0, RowVersion: 0, Enabled: 1 }), '可观测策略已创建。'); if (result) { policyOpen.value = false; await load() } }
function openPolicyTest(row?: Row) { if (row?.Id) { testForm.PolicyId = String(row.Id); testForm.UseConfiguredSignal = row.EvaluationMode !== 'Manual' } else testForm.PolicyId ||= String(data.value.Policies[0]?.Id || ''); testForm.EventId = `manual-${Date.now()}`; testOpen.value = true }
async function evaluatePolicy() { if (!testForm.PolicyId || !testForm.EventId) { action.status = 'error'; action.message = '策略和事件Id不能为空。'; return } const payload: Row = { PolicyId: testForm.PolicyId, EventId: testForm.EventId, Title: '治理中心策略评估', Context: { Source: 'AI平台治理中心' } }; if (!testForm.UseConfiguredSignal) payload.ObservedValue = testForm.ObservedValue; const result = await act(() => runEngine(props.context, 'mci-alert-evaluate-manual', payload), '策略评估完成。'); if (result) { testOpen.value = false; testForm.EventId = `manual-${Date.now()}`; await load() } }
async function transitionAlert(row: Row, command: string, text = '') { const result = await act(() => runEngine(props.context, 'mci-alert-transition', { AlertId: row.Id, Action: command, ExpectedStatus: row.Status, Resolution: text }), '告警状态已更新。'); if (result) await load() }
function prepareResolve(row: Row) { resolveTarget.value = row; resolution.value = ''; resolveOpen.value = true }
async function resolveAlert() { if (!resolveTarget.value || !resolution.value) { action.status = 'error'; action.message = '解决结论不能为空。'; return } await transitionAlert(resolveTarget.value, 'Resolve', resolution.value); if (action.status === 'success') resolveOpen.value = false }
async function queryTrace() { if (!/^[0-9a-fA-F]{32}$/.test(traceForm.TraceId)) { action.status = 'error'; action.message = 'TraceId必须是32位十六进制。'; return } traceBusy.value = true; try { traceResult.value = await runEngine<TraceResult>(props.context, 'mci-trace-timeline', { ...traceForm, PageSize: 500 }); action.status = 'success'; action.message = `已读取 ${traceResult.value.SpanCount} 个 Span。` } catch (e) { action.status = 'error'; action.message = e instanceof Error ? e.message : 'Trace查询失败'; traceResult.value = null } finally { traceBusy.value = false } }
async function createLogPolicy() { if (!logPolicyForm.PolicyKey || !logPolicyForm.Name) { action.status = 'error'; action.message = '日志策略Key和名称不能为空。'; return } if (!(logPolicyForm.HotDays <= logPolicyForm.WarmDays && logPolicyForm.WarmDays <= logPolicyForm.ColdDays)) { action.status = 'error'; action.message = '留存天数必须满足热 ≤ 温 ≤ 冷。'; return } let match: unknown, redaction: unknown; try { match = parseJson(logPolicyForm.MatchJson, '匹配'); redaction = parseJson(logPolicyForm.RedactionJson, '脱敏规则') } catch (e) { action.status = 'error'; action.message = (e as Error).message; return } const result = await act(() => addRow(props.context, 'mci_log_policy', { ...logPolicyForm, MatchJson: JSON.stringify(match), RedactionJson: JSON.stringify(redaction), LegalHold: logPolicyForm.LegalHold ? 1 : 0, Enabled: 1 }), '日志生命周期策略已创建。'); if (result) { logPolicyOpen.value = false; await load() } }
async function planLifecycle(row: Row) { const result = await act(() => runEngine<LifecyclePlan>(props.context, 'mci-log-lifecycle-plan', { PolicyId: row.Id }), '日志生命周期执行计划已生成。'); if (result) { lifecycleTarget.value = row; lifecyclePlan.value = result; lifecycleOpen.value = true } }
async function executeLifecycle() { if (!lifecycleTarget.value || !lifecyclePlan.value || !lifecyclePlan.value.CanExecute) { action.status = 'error'; action.message = lifecyclePlan.value?.BlockReason || '当前计划不可执行。'; return } const runKey = `log-${lifecycleTarget.value.Id}-${lifecyclePlan.value.PlanHash.slice(0, 28)}`; const result = await act(() => runBackground<Row>(props.context, 'mci-log-lifecycle-execute', { PolicyId: lifecycleTarget.value?.Id, ExpectedPlanHash: lifecyclePlan.value?.PlanHash, RunKey: runKey }, `日志生命周期：${lifecycleTarget.value?.Name}`, { IdempotencyKey: runKey, ConcurrencyKey: `mci-log:${lifecycleTarget.value?.Id}`, MaxAttempts: 3 }), '日志生命周期任务已进入持久队列。'); if (result) { lifecycleOpen.value = false; await load() } }
async function createRoute() { if (!routeForm.RouteKey || !routeForm.Name) { action.status = 'error'; action.message = '路由Key和名称不能为空。'; return } let match: unknown, channels: unknown, escalation: unknown; try { match = parseJson(routeForm.MatchJson, '匹配'); channels = parseJson(routeForm.ChannelsJson, '渠道'); escalation = parseJson(routeForm.EscalationJson, '升级链') } catch (e) { action.status = 'error'; action.message = (e as Error).message; return } const result = await act(() => addRow(props.context, 'mci_alert_route', { ...routeForm, MatchJson: JSON.stringify(match), ChannelsJson: JSON.stringify(channels), ScheduleJson: '{}', EscalationJson: JSON.stringify(escalation), Enabled: 1 }), '告警路由已创建。'); if (result) { routeOpen.value = false; await load() } }
onMounted(load)
</script>

