 margin: 0; padding: 0; list-style: none; }.run-list li { display: grid; grid-template-columns: 9px minmax(0,1fr); gap: 9px; }.run-list li > span { width: 8px; height: 8px; margin-top: 5px; border-radius: 50%; background: var(--mci-color-warning); }.run-list li > span[data-state="Completed"] { background: var(--mci-color-success); }.run-list li > span[data-state="Failed"], .run-list li > span[data-state="CompletedWithErrors"] { background: var(--mci-color-danger); }.run-list div { display: grid; gap: 2px; }.run-list small { color: var(--mci-text-secondary); }.run-list code { overflow: hidden; color: var(--mci-text-tertiary); font-size: 10px; text-overflow: ellipsis; white-space: nowrap; }.route-list { display: grid; gap: 8px; }.route-list article { display: grid; grid-template-columns: 34px minmax(0,1fr); align-items: center; gap: 9px; padding: 9px; border: 1px solid var(--mci-border-color); border-radius: var(--mci-shape-input); background: var(--mci-bg-soft); }.route-list article > span { display: grid; width: 32px; height: 32px; place-items: center; border-radius: 9px; color: var(--mci-color-primary); background: var(--mci-bg-elevated); font-family: var(--mci-font-mono); }.route-list article div { display: grid; gap: 2px; }.route-list small { color: var(--mci-text-secondary); }.delivery-table { margin-top: 12px; }.feedback { padding: 10px; border-radius: var(--mci-shape-input); background: var(--mci-bg-soft); }.feedback[data-state="error"] { color: var(--mci-color-danger); }.feedback[data-state="success"] { color: var(--mci-color-success); }.form-grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 12px; }.form-grid .full { grid-column: 1 / -1; }.hold-check { display: flex; align-items: center; gap: 8px; }.hold-check input { width: 18px; height: 18px; }.blocked { color: var(--mci-color-danger); font-weight: 700; }
